const input = $input.first();
let text = '';
if (typeof input.json === 'string') text = input.json;
else if (input.json.data) text = input.json.data;
else if (input.binary) text = Buffer.from(input.binary.data.data, 'base64').toString('utf-8');

const lines = text.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.trim());

const result = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim()) continue;
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let char of line) {
    if (char === '"') inQuotes = !inQuotes;
    else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else current += char;
  }
  values.push(current.trim());
  const obj = {};
  headers.forEach((h, idx) => obj[h] = values[idx] || '');
  result.push({ json: obj });
}
return result;

const input = $input.first();
let text = '';
if (typeof input.json === 'string') text = input.json;
else if (input.json.data) text = input.json.data;
else if (input.binary) text = Buffer.from(input.binary.data.data, 'base64').toString('utf-8');

const lines = text.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.trim());

const result = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim()) continue;
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let char of line) {
    if (char === '"') inQuotes = !inQuotes;
    else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else current += char;
  }
  values.push(current.trim());
  const obj = {};
  headers.forEach((h, idx) => obj[h] = values[idx] || '');
  result.push({ json: obj });
}
return result;

const newsByDate = {};
for (const item of $input.all()) {
  let d = item.json.date || (item.json.datetime ? item.json.datetime.split(' ')[0] : '');
  if (!d) continue;
  if (!newsByDate[d]) newsByDate[d] = [];
  newsByDate[d].push(item.json.title);
}
return [{ json: { newsByDate } }];

const allItems = $input.all();
let newsLookup = {};
const marketData = [];

for (const item of allItems) {
  if (item.json.newsByDate) newsLookup = item.json.newsByDate;
  else if (item.json.date) marketData.push(item);
}

marketData.sort((a, b) => new Date(a.json.date) - new Date(b.json.date));

const merged = [];
for (const item of marketData) {
  let d = item.json.date.split(' ')[0];
  const news = newsLookup[d] || [];
  const newsText = news.length > 0 ? news.slice(0, 3).join(' | ') : "Market is quiet today.";

  merged.push({
    json: {
      ...item.json,
      news_text: newsText,
      news_count: news.length
    }
  });
}

return merged;

// Simple Batch Preparation
const allItems = $input.all();
const inputsArray = allItems.map(item => item.json.news_text);

// We store original items to merge later
return [{
  json: {
    batch_inputs: inputsArray,
    original_items: allItems.map(i => i.json)
  }
}];

const item = $input.first();
const api = item.json.data || item.json;

const originalItems = $("4. Prepare Batch").first()?.json?.original_items;
if (!originalItems) throw new Error("Missing original_items");

let sentiments = api;
if (Array.isArray(api) && Array.isArray(api[0])) sentiments = api;
else if (!Array.isArray(api)) sentiments = [api];

const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const mean = a => (a.length ? a.reduce((s, v) => s + v, 0) / a.length : 0);
const std = a => {
  if (!a.length) return 0;
  const m = mean(a);
  return Math.sqrt(mean(a.map(v => (v - m) ** 2)));
};
const daysBetween = (d1, d2) =>
  Math.round((Date.parse(d2 + "T00:00:00Z") - Date.parse(d1 + "T00:00:00Z")) / 86400000);

const pickBestSentiment = s => {
  let best = { score: 0, label: "NEUTRAL" };
  if (Array.isArray(s)) best = s.reduce((p, c) => (+c.score > +p.score ? c : p), best);
  else if (s && typeof s === "object") best = { score: +(s.score ?? 0), label: String(s.label ?? "NEUTRAL") };
  return { score: +best.score || 0, label: String(best.label || "NEUTRAL").toUpperCase() };
};

const toDay = d => String(d).split(" ")[0].split("T")[0];
const computeEMA = (series, period) => {
  const k = 2 / (period + 1);
  let ema = null;
  return series.map(v => (ema = ema === null ? v : v * k + ema * (1 - k)));
};

const byTicker = {};
for (const r of originalItems) {
  const t = r.ticker;
  (byTicker[t] ??= []).push({
    date: toDay(r.date),
    price: parseFloat(r.price ?? r.close),
    rsi: parseFloat(r.rsi ?? 50),
    vol: parseFloat(r.volatility_7d ?? r.volatility ?? 0),
  });
}
for (const t of Object.keys(byTicker)) byTicker[t].sort((a, b) => a.date.localeCompare(b.date));

for (const t of Object.keys(byTicker)) {
  const prices = byTicker[t].map(x => x.price);
  const ema10 = computeEMA(prices, 10);
  const ema30 = computeEMA(prices, 30);
  for (let i = 0; i < byTicker[t].length; i++) byTicker[t][i].trendUp = ema10[i] > ema30[i];
}

const tickers = Object.keys(byTicker);
const START_CAPITAL = 10000;
const initialCapitalPerTicker = START_CAPITAL / Math.max(1, tickers.length);

const portfolio = {};
for (const t of tickers) {
  portfolio[t] = {
    balance: initialCapitalPerTicker,
    coin: 0,
    inPosition: false,
    entryPrice: 0,
    entryDate: null,
    lastEquity: initialCapitalPerTicker,
    peakPriceSinceEntry: 0,
  };
}

const allDates = [...new Set(originalItems.map(r => toDay(r.date)))].sort();
const mapTD = {};
for (const t of tickers) {
  mapTD[t] = {};
  for (const row of byTicker[t]) mapTD[t][row.date] = row;
}

const sentimentMap = {};
for (let i = 0; i < Math.min(originalItems.length, sentiments.length); i++) {
  const d = toDay(originalItems[i].date);
  const t = originalItems[i].ticker;
  sentimentMap[`${d}__${t}`] = sentiments[i];
}

const RISK_PER_TRADE_PCT = 0.02, MAX_POSITION_PCT = 0.60;
const STOP_LOSS_PCT = 0.05, TAKE_PROFIT_PCT = 0.08, TRAIL_STOP_PCT = 0.05, TIME_STOP_DAYS = 4;
const SENT_ENTRY_MIN = 0.65, SENT_EXIT_MIN = 0.70;
const RSI_REBOUND = 38, RSI_UPPER = 70, RSI_OVERSOLD_BOUNCE = 30;

const trades = [];
let totalOrders = 0, winningTrades = 0, totalProfit = 0, totalLoss = 0;
const equityCurve = [];
let peak = -Infinity, maxDrawdown = 0;

for (const date of allDates) {
  for (const t of tickers) {
    const row = mapTD[t][date];
    if (!row || !Number.isFinite(row.price)) continue;

    const price = row.price;
    const rsi = Number.isFinite(row.rsi) ? row.rsi : 50;
    const trendUp = !!row.trendUp;
    const w = portfolio[t];

    const { label: sentimentLabel, score: sentimentScore } = pickBestSentiment(sentimentMap[`${date}__${t}`]);

    const currentEquity = w.balance + w.coin * price;
    w.lastEquity = currentEquity;
    if (w.inPosition) w.peakPriceSinceEntry = Math.max(w.peakPriceSinceEntry, price);

    const trendEntry =
      !w.inPosition && trendUp && rsi >= RSI_REBOUND && rsi <= RSI_UPPER &&
      sentimentLabel === "POSITIVE" && sentimentScore >= SENT_ENTRY_MIN;

    const bounceEntry =
      !w.inPosition && rsi <= RSI_OVERSOLD_BOUNCE &&
      sentimentLabel === "POSITIVE" && sentimentScore >= SENT_ENTRY_MIN;

    const canEnter = trendEntry || bounceEntry;

    let exitReason = "";
    if (w.inPosition) {
      const pnlPct = (price - w.entryPrice) / w.entryPrice;

      if (pnlPct <= -STOP_LOSS_PCT) exitReason = "Stop Loss";
      else if (pnlPct >= TAKE_PROFIT_PCT) exitReason = "Take Profit";
      else {
        const peakP = w.peakPriceSinceEntry || w.entryPrice;
        const trailLevel = peakP * (1 - TRAIL_STOP_PCT);
        if (price < trailLevel && peakP > w.entryPrice * (1 + 0.015)) exitReason = "Trailing Stop";
      }

      if (!exitReason && sentimentLabel === "NEGATIVE" && sentimentScore >= SENT_EXIT_MIN) exitReason = "Negative Sentiment Exit";

      if (!exitReason && w.entryDate) {
        const held = daysBetween(w.entryDate, date);
        if (held >= TIME_STOP_DAYS && pnlPct < 0.015) exitReason = "Time Stop";
      }
    }

    if (canEnter) {
      const riskDollars = currentEquity * RISK_PER_TRADE_PCT;
      let positionValue = riskDollars / STOP_LOSS_PCT;
      positionValue = Math.min(positionValue, currentEquity * MAX_POSITION_PCT, w.balance);

      const vol = +row.vol || 0;
      if (Number.isFinite(vol) && vol > 0) positionValue *= clamp(1 / (1 + vol * 2.5), 0.30, 1);

      if (positionValue > 5) {
        w.entryPrice = price;
        w.entryDate = date;
        w.peakPriceSinceEntry = price;
        w.coin = positionValue / price;
        w.balance -= positionValue;
        w.inPosition = true;

        trades.push({
          date, ticker: t, price,
          decision: "buy",
          rsi,
          sentiment_label: sentimentLabel,
          sentiment_score: sentimentScore.toFixed(2),
          reason: trendEntry ? "Trend Entry" : "Bounce Entry"
        });
      }
    } else if (exitReason && w.inPosition) {
      const sellValue = w.coin * price;
      const costBasis = w.coin * w.entryPrice;
      const pnl = sellValue - costBasis;

      if (pnl > 0) { winningTrades++; totalProfit += pnl; }
      else totalLoss += Math.abs(pnl);

      totalOrders++;

      w.balance += sellValue;
      w.coin = 0;
      w.inPosition = false;
      w.entryPrice = 0;
      w.entryDate = null;
      w.peakPriceSinceEntry = 0;

      trades.push({
        date, ticker: t, price,
        decision: "sell",
        pnl: pnl.toFixed(2),
        rsi,
        sentiment_label: sentimentLabel,
        sentiment_score: sentimentScore.toFixed(2),
        reason: exitReason
      });
    }
  }

  let totalEq = 0;
  for (const t of tickers) totalEq += portfolio[t].lastEquity;
  equityCurve.push(totalEq);

  if (totalEq > peak) peak = totalEq;
  const dd = peak > 0 ? (peak - totalEq) / peak : 0;
  if (dd > maxDrawdown) maxDrawdown = dd;
}

const dailyReturns = [];
for (let i = 1; i < equityCurve.length; i++) {
  const prev = equityCurve[i - 1], curr = equityCurve[i];
  dailyReturns.push(prev !== 0 ? (curr - prev) / prev : 0);
}

const sharpeRatio = (() => {
  const sd = std(dailyReturns);
  return sd !== 0 ? (mean(dailyReturns) / sd) * Math.sqrt(365) : 0;
})();

const finalTotalEquity = equityCurve[equityCurve.length - 1] || START_CAPITAL;
const totalReturn = ((finalTotalEquity - START_CAPITAL) / START_CAPITAL) * 100;
const winRate = totalOrders > 0 ? (winningTrades / totalOrders) * 100 : 0;
const profitFactor = totalLoss > 0 ? (totalProfit / totalLoss) : (totalProfit > 0 ? 999 : 0);
const totalTransactions = trades.length;

return [{
  json: {
    metric_summary: {
      "Total Transactions": totalTransactions,
      "Total Orders": totalOrders,
      "Win Rate": winRate.toFixed(2) + "%",
      "Profit Factor": profitFactor.toFixed(2),
      "Total Return": totalReturn.toFixed(2) + "%",
      "Sharpe Ratio": sharpeRatio.toFixed(2),
      "Max Drawdown": "-" + (maxDrawdown * 100).toFixed(2) + "%",
      "Final Balance": "$" + finalTotalEquity.toFixed(2)
    },
    trade_log: trades
  }
}];

const input = $input.first();
const trades = input.json.trade_log;
const summary = input.json.metric_summary;

if (!trades) throw new Error("No trade data");
if (!summary) throw new Error("No metric_summary");

const tradesHeader  = 'date,ticker,price,decision,rsi,sentiment,reason\n';
const tradesRows  = trades.map(t => {
  const safeReason = (t.reason || '').replace(/"/g, "'");
  return `${t.date},${t.ticker},${t.price},${t.decision},${t.rsi},${t.sentiment_label},"${safeReason}"`;
}).join('\n');

const tradesCsv = tradesHeader + tradesRows;

const metricsHeader = 'metric,value\n';
const metricsRows = Object.entries(summary).map(([k, v]) => {
  const safeKey = String(k).replace(/"/g, '""');
  const safeVal = String(v ?? '').replace(/"/g, '""');
  return `"${safeKey}","${safeVal}"`;
}).join('\n');

const metricsCsv = metricsHeader + metricsRows;


return [{
  binary: {
    data: {
      data: Buffer.from(tradesCsv).toString('base64'),
      mimeType: 'text/csv',
      fileName: 'final_results.csv'
    },
    metrics: {
      data: Buffer.from(metricsCsv).toString('base64'),
      mimeType: 'text/csv',
      fileName: 'metrics.csv'
    }
  }
}];
